const raw = $input.first().json.stdout;
const parsed = JSON.parse(raw);
return parsed.findings.map(finding => ({ json: finding }));

const llmOutput = $input.first().json.text
  || ($input.first().json.content?.[0]?.text)
  || '';
const parts = llmOutput.split('---CAPTION_END---');
const caption = (parts[0] || '').trim().slice(0, 1024);
const script  = (parts[1] || '').trim().slice(0, 3200);
return [{ json: { caption, script } }];
